async function requestRepository(url: URL, startupRepository: string): Promise<string> {
  const requested = url.searchParams.get("repository");
  return requested === null ? startupRepository : resolveRepository(requested);
}

function currentTemporalRequestTime(now = new Date()): string {
  const wholeSecond = new Date(now.getTime());
  wholeSecond.setUTCMilliseconds(0);
  return wholeSecond.toISOString();
}

type TemporalQuery = Readonly<{
  view: TemporalView;
  request_time: string;
  world_at?: string;
  known_at: string;
  transition?: TemporalTransition;
}>;

type TemporalTransition = Readonly<{
  from: string;
  to: string;
}>;

